import SwiftUI
import AtiCleanerCore
struct UninstallerView:View{@State private var apps:[InstalledApp]=[];@State private var query="";var filtered:[InstalledApp]{query.isEmpty ? apps : apps.filter{$0.name.localizedCaseInsensitiveContains(query)}};var body:some View{VStack(alignment:.leading,spacing:16){PageHeader(icon:"xmark.app",title:"Uygulama Kaldırıcı",subtitle:"Yüklü uygulamaları otomatik listeleyin ve seçtiklerinizi Çöp Kutusu'na taşıyın.",tint:Theme.uninstall);TextField("Uygulama ara…",text:$query).textFieldStyle(.roundedBorder);if apps.isEmpty{ProgressView("Uygulamalar listeleniyor…")}else{List(filtered){app in HStack{Image(systemName:"app.fill").foregroundStyle(Theme.uninstall);VStack(alignment:.leading){Text(app.name).font(.headline);Text(app.bundleIdentifier ?? app.path).font(.caption).foregroundStyle(.secondary)};Spacer();Text(app.size.formattedBytes).monospacedDigit().foregroundStyle(.secondary);Button("Finder"){NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath:app.path)])}}}}.padding(24).task{apps=await Task.detached{AppScanner.installedApps()}.value}}}
